#ifndef ML_PLATFORM_H
#define ML_PLATFORM_H

/**
 * @brief This header file relies on defines generated by ml_platform.cmake :
 * PLATFORM_PICO, PLATFORM_RP2040, PLATFORM_RP2350, PLATFORM_ESP32, PLATFORM_ESP32S2,
 * PLATFORM_ESP32S3, PLATFORM_ESP32C2, ...
 * and we check here for native ESP-IDF macros (ESP_PLATFORM, CONFIG_IDF_TARGET_*).
 *
 * @note This file should be included after the platform-specific macros have been defined.
 */

//=========================================================================
// Macros defined by this include :
//
//	ML_DEBUG_MODE				-> Set if compiled with debug informations
//	ML_PLATFORM_PICO			-> Set if we are under the Pico SDK
//		ML_PICO_RP2040		-> Set if we are targeting RP2040 (Pico)
//		ML_PICO_RP2350		-> Set if we are targeting RP2350 (Pico2)
//		ML_PLATFORM_PICOW		-> Set if we are targeting a Pico with Wifi support
//		ML_PICO_RP2040_W		-> Set if we are targeting a Pico (RP2040) with Wifi Support
//		ML_PICO_RP2350_W		-> Set if we are targeting a Pico2 (RP2350) with Wifi Support
//
//	ML_PLATFORM_ESP 			-> Set if we are under the ESP-IDF SDK
//		ML_ESP_ESP32_ORIG		-> ESP32
//		ML_ESP_ESP32S2		-> S2
//		ML_ESP_ESP32S3		-> S3
//		ML_ESP_ESP32C2		-> C2
//		ML_ESP_ESP32C3		-> C3
//		ML_ESP_ESP32C6		-> C6
//		ML_ESP_ESP32H2		-> H2
//		ML_ESP_ESP32P4		-> P4
//
//=========================================================================

// --- Base platform -------------------------------------------------

#if defined(PLATFORM_PICO) || defined(PLATFORM_RP2040) || defined(PLATFORM_RP2350)
#define ML_PLATFORM_PICO 1
#if defined(PLATFORM_PICOW)
#define ML_PLATFORM_PICOW 1
#if defined(PLATFORM_RP2040)
#define ML_PICO_RP2040_W 1
#elif defined(PLATFORM_RP2350)
#define ML_PICO_RP2350_W 1
#endif
#endif
#endif

#if defined(PLATFORM_ESP32) || defined(ESP_PLATFORM)
#define ML_PLATFORM_ESP 1
#endif

// --- PICO ------------------------------------------------------

/* we rely on the CMake macros (since there is no equivalent
   "CONFIG_RP2040" standard on the C side). */

#if defined(PLATFORM_RP2040)
#define ML_PICO_RP2040 1
#endif
#if defined(PLATFORM_RP2350)
#define ML_PICO_RP2350 1
#endif

#if defined(DEBUG_MODE)
#define ML_DEBUG_MODE 1
#endif

#if defined(NDEBUG)
#undef ML_DEBUG_MODE
#endif

// --- ESP ---------------------------------

#if defined(ESP_PLATFORM)

/* Espressif generate CONFIG_IDF_TARGET_* under sdkconfig.h */

#if defined(CONFIG_IDF_TARGET_ESP32)
#define ML_ESP_ESP32_ORIG 1
#elif defined(CONFIG_IDF_TARGET_ESP32S2)
#define ML_ESP_ESP32S2 1
#elif defined(CONFIG_IDF_TARGET_ESP32S3)
#define ML_ESP_ESP32S3 1
#elif defined(CONFIG_IDF_TARGET_ESP32C2)
#define ML_ESP_ESP32C2 1
#elif defined(CONFIG_IDF_TARGET_ESP32C3)
#define ML_ESP_ESP32C3 1
#elif defined(CONFIG_IDF_TARGET_ESP32C6)
#define ML_ESP_ESP32C6 1
#elif defined(CONFIG_IDF_TARGET_ESP32H2)
#define ML_ESP_ESP32H2 1
#elif defined(CONFIG_IDF_TARGET_ESP32P4)
#define ML_ESP_ESP32P4 1
#endif

/* if sdkconfig.h is not yet included at the time of ml_platform.h,
   we can fall back on the CMake defines propagated by ml_platform.cmake. */

#elif defined(PLATFORM_ESP32_ORIG)
#define ML_ESP_ESP32_ORIG 1
#elif defined(PLATFORM_ESP32S2)
#define ML_ESP_ESP32S2 1
#elif defined(PLATFORM_ESP32S3)
#define ML_ESP_ESP32S3 1
#elif defined(PLATFORM_ESP32C2)
#define ML_ESP_ESP32C2 1
#elif defined(PLATFORM_ESP32C3)
#define ML_ESP_ESP32C3 1
#elif defined(PLATFORM_ESP32C6)
#define ML_ESP_ESP32C6 1
#elif defined(PLATFORM_ESP32H2)
#define ML_ESP_ESP32H2 1
#elif defined(PLATFORM_ESP32P4)
#define ML_ESP_ESP32P4 1
#endif

#endif // ML_PLATFORM_H
